from pathlib import Path
import html,json,csv
B=Path(__file__).resolve().parents[1];D=B/'data';E=lambda x:html.escape(str(x))
def main():
 bands=[]
 for i,(y,h) in enumerate([(225,143),(370,59),(431,75),(508,71),(582,57),(642,60)],1):bands.append({'id':f'F{i:02}','box_xywh':[220,y,400,h],'surface':'upper main view','unit':'photographic band, not proven line/word'})
 for i,(y,h) in enumerate([(922,186),(1111,75),(1189,64),(1255,78)],1):bands.append({'id':f'B{i:02}','box_xywh':[235,y,390,h],'surface':'lower main view','unit':'photographic band, not proven line/word'})
 (D/'round21_U04_bands.json').write_text(json.dumps(bands,ensure_ascii=False,indent=2)+'\n')
 svg=['<svg xmlns="http://www.w3.org/2000/svg" viewBox="200 215 440 1165"><image href="../sources/round21_U04.jpg" width="836" height="1420"/>']
 for r in bands:
  x,y,w,h=r['box_xywh'];svg.append(f'<rect x="{x}" y="{y}" width="{w}" height="{h}" fill="none" stroke="#4edccb" stroke-width="2"/><rect x="{x}" y="{y}" width="39" height="18" fill="#102837"/><text x="{x+3}" y="{y+14}" fill="white" font-family="sans-serif" font-size="12">{r["id"]}</text>')
 svg.append('</svg>');(D/'round21_U04_bands.svg').write_text(''.join(svg))
 meta=json.loads((D/'round21_prior_sample_metadata.json').read_text())['records'];acq=json.loads((D/'round21_acquisition_manifest.json').read_text())
 with (D/'round21_heldout_matches.csv').open(encoding='utf-8-sig') as f:results=list(csv.DictReader(f))
 s='''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Цикл21 · границы и варианты знаков</title><style>body{font:18px/1.6 system-ui;background:#f3f0e8;color:#20303b;max-width:1350px;margin:auto;padding:28px}a{color:#145c85}.note{padding:20px;background:#e6dfcd;border-left:4px solid #7c6748}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:20px}figure{margin:0;padding:16px;background:#fff;border:1px solid #ccc}img{max-width:100%;height:auto}.detail img{width:auto}figcaption{font-size:16px}small{display:block}table{width:100%;border-collapse:collapse;background:white;font-size:15px}td,th{border:1px solid #ccc;padding:10px;text-align:left;vertical-align:top}.scroll{overflow:auto}summary{cursor:pointer}object{width:100%;height:850px}@media(max-width:700px){body{padding:15px}object{height:600px}}</style><h1>Границы и варианты знаков</h1><p>Связанный цикл21 ·25 октября2026</p><p class="note">Готовые индивидуальные чтения и переводы не открывались. По метаданным прежние15 памятников относятся к УрукуIII/IV, язык в каталоге — «неопределённый». Новая серия из8 фотонаборов отдельно отобрана по каталожным признакам UrIII и Sumerian. Эти атрибуции не являются нашей независимой датировкой или расшифровкой.</p><p><a href="observations/2026-10-25_round21_boundaries_and_strata.txt">Полный отчёт</a> · <a href="data/round21_heldout_matches.csv">Все12 проверочных сопоставлений</a> · <a href="data/round21_inventory_decisions.json">Решения по реестру</a></p><h2>Проверяемые конфигурации</h2><p>W01 — стек коротких приблизительно горизонтальных следов со стоячим элементом сбоку. W02 — веерообразная форма с внутренними штрихами. BUNDLE — контрольный рисунок пучка; не признан самостоятельной единицей письма. Два ясных штриха не считаются автоматически тремя.</p><div class="grid">'''
 examples=[('F1','Кандидат W01, исходный пример. Точное число следов и контакты требуют осторожности.'),('F2','Соседний сходный комплекс; самостоятельное звучание неизвестно.'),('U06_W01','Проверочная серия: различимы три следа и стоячий элемент.'),('U08_W01','Проверочная серия: кандидат по тому же критерию.'),('U05_W01','Частичное совпадение: две ясные полосы, третья не доказана.'),('U07_W01_full','Частичное совпадение: увеличенная область вместо обрезанного первоначального фрагмента.'),('P1','Кандидат веерообразной формы; точные контакты остаются спорными.'),('U07_W02_first','Первый повтор веерообразной конфигурации на новом снимке.'),('U07_W02_middle','Ещё один повтор на том же предмете, не независимый новый предмет.'),('U08_W02','Кандидат веерообразного комплекса в проверочной серии.'),('U05_W02','Внутренние следы и внешний контур различимы.'),('U05_background','Шалловый параллельный рисунок на поверхности не засчитан автоматически как тот же знак.')]
 for n,cap in examples:
  s+='<figure class="detail"><img src="data/round21_'+n+'_native.jpg" alt="'+E(n)+'"><figcaption><b>'+E(n)+'</b><small>'+E(cap.replace('Шалловый','Неглубокий'))+'</small></figcaption></figure>'
 s+='</div><h2>Результаты отложенной проверки</h2><p>Критерии зафиксированы до открытия U05–U08. Пять строгих визуальных кандидатов, пять частичных, один неоцениваемый и один без наблюдаемого совпадения. Это не частота родства и не подтверждение фонетического алфавита.</p><div class="scroll"><table><tr><th>Снимок</th><th>Кандидат</th><th>Статус</th><th>Наблюдение</th></tr>'
 for r in results:s+='<tr>'+''.join('<td>'+E(r[k])+'</td>' for k in ['image','candidate','status','observation'])+'</tr>'
 s+='</table></div><h2>Карта разделительных полос U04</h2><p>Шесть областей основного верхнего вида и четыре нижнего. Это навигационная разметка фотографии, не установленное число строк, слов или предложений. Рамки и метки добавлены поверх исходного снимка.</p><object data="data/round21_U04_bands.svg" type="image/svg+xml"></object><h2>Все восемь новых фотонаборов</h2><div class="grid">'
 for r in acq:
  s+='<figure><a href="'+E(r['image_file'])+'"><img loading="lazy" src="'+E(r['image_file'])+'" style="max-height:550px" alt="'+E(r['label'])+'"></a><figcaption><b>'+E(r['label'])+'</b><small>'+('Разработка критериев' if int(r['label'][1:])<=4 else 'Отложенная проверка')+'</small></figcaption></figure>'
 s+='</div><details><summary>Метаданные прежней выборки — только период и язык</summary><table><tr><th>Снимок</th><th>Период в каталоге</th><th>Язык в каталоге</th></tr>'
 for r in meta:s+='<tr><td>'+E(r['label'])+'</td><td>'+E(r['period'])+'</td><td>'+E(r['language'])+'</td></tr>'
 s+='</table></details><p>Звук, слог и значение новых конфигураций не назначены. Происхождение и контрольные суммы сохранены в реестре. Переход ранней формы в позднюю и казакское соответствие не установлены. Книга не изменялась.</p></html>'
 (B/'comparison_round21.html').write_text(s);print('Atlas built:8 photos,12 diagnostic panels,10 mapped bands,12 heldout results.')
if __name__=='__main__':main()
